class Solution {
    public String stoneGameIII(int[] stoneValue){
        int n=stoneValue.length;
        int[] dp=new int[n+1];
        for(int i=n-1;i>=0;i--){
            dp[i]=Integer.MIN_VALUE;
            int sum=0;
            for(int take=1;take<=3&&i+take<=n;take++){
                sum+=stoneValue[i+take-1];
                dp[i]=Math.max(dp[i],sum-dp[i+take]);
            }
        }
        return dp[0]>0?"Alice":dp[0]<0?"Bob":"Tie";
    }
}

code.kotlin:
class Solution {
    fun stoneGameIII(stoneValue:IntArray):String{
        val n=stoneValue.size;
        val dp=IntArray(n+1);
        for(i in n-1 downTo 0){
            dp[i]=Int.MIN_VALUE;
            var sum=0;
            for(take in 1..3)if(i+take<=n){
                sum+=stoneValue[i+take-1];
                dp[i]=maxOf(dp[i],sum-dp[i+take])
            }
        };
        return if(dp[0]>0)"Alice" else if(dp[0]<0)"Bob" else "Tie"
    }
}

